    def fmt(g):
        return f'{len(g)} {len(g[0])}\n' + '\n'.join(' '.join(map(str, row)) for row in g)
    def rand_grid(r, c, p):
        while True:
            g = [[1 if rng.random() < p else 0 for _ in range(c)] for _ in range(r)]
            if sum(map(sum, g)) >= 2:
                return g
    tests = [fmt([[1, 1]]), fmt([[1], [1]]), fmt([[1, 0, 0, 1], [0, 0, 0, 0], [0, 1, 0, 0]]),
